Widget _appBar(String title, {Color color = _burgundy, VoidCallback? onBack, List<Widget>? actions}) => AppBar(
  backgroundColor: color,
  foregroundColor: Colors.white,
  centerTitle: true,
  title: Text(title, style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w900)),
  leading: onBack == null ? null : IconButton(onPressed: onBack, icon: const Icon(Icons.arrow_back_rounded)),
  actions: actions,
);

Widget _pill(String text, Color color, {IconData? icon}) => Container(
  padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
  decoration: BoxDecoration(color: color.withOpacity(.10), borderRadius: BorderRadius.circular(9), border: Border.all(color: color.withOpacity(.18))),
  child: Row(mainAxisSize: MainAxisSize.min, children: [if (icon != null) ...[Icon(icon, size: 13, color: color), const SizedBox(width: 4)], Text(text, style: TextStyle(fontSize: 9, fontWeight: FontWeight.w900, color: color))]),
);

Widget _section(String title, {IconData? icon, Color color = _burgundy, String? action, VoidCallback? onAction}) => Padding(
  padding: const EdgeInsets.only(bottom: 8),
  child: Row(children: [
    if (icon != null) Container(width: 28, height: 28, decoration: BoxDecoration(color: color.withOpacity(.10), borderRadius: BorderRadius.circular(9)), child: Icon(icon, size: 16, color: color)),
    if (icon != null) const SizedBox(width: 8),
    Expanded(child: Text(title, textAlign: TextAlign.right, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w900, color: _ink))),
    if (action != null) TextButton(onPressed: onAction, child: Text(action, style: TextStyle(fontSize: 9, fontWeight: FontWeight.w900, color: color))),
  ]),
);

