      const SizedBox(height: 8),
      PageCard(child: Row(children: [const Icon(Icons.smartphone_rounded, color: _burgundy), const SizedBox(width: 7), Expanded(child: TextField(controller: phone, textDirection: TextDirection.ltr, keyboardType: TextInputType.phone, maxLength: 9, inputFormatters: [FilteringTextInputFormatter.digitsOnly], decoration: const InputDecoration(labelText: 'رقم الهاتف / الاشتراك', counterText: '', isDense: true, border: InputBorder.none)))])),
      const SizedBox(height: 8),
      if (['yemen_mobile','you','sabafon','y'].contains(operator)) ...[
        Row(children: [Expanded(child: ChoiceChip(selected: tab == 'balance', label: const Text('رصيد', style: TextStyle(fontSize: 10, fontWeight: FontWeight.w900)), onSelected: (_) => setState(() => tab = 'balance'))), const SizedBox(width: 7), Expanded(child: ChoiceChip(selected: tab == 'packages', label: const Text('باقات', style: TextStyle(fontSize: 10, fontWeight: FontWeight.w900)), onSelected: (_) => setState(() => tab = 'packages')))]),
      ],
      const SizedBox(height: 8),
      if (operator == 'yemen_net') ...[
        Row(children: [Expanded(child: ChoiceChip(selected: netTab == 'adsl', label: const Text('الإنترنت الأرضي', style: TextStyle(fontSize: 9, fontWeight: FontWeight.w900)), onSelected: (_) => setState(() => netTab = 'adsl'))), const SizedBox(width: 7), Expanded(child: ChoiceChip(selected: netTab == 'phone', label: const Text('الهاتف', style: TextStyle(fontSize: 9, fontWeight: FontWeight.w900)), onSelected: (_) => setState(() => netTab = 'phone')))]),
        const SizedBox(height: 8),
      ],
      if (tab == 'balance' && ['yemen_mobile','yemen4g','yemen_net','y'].contains(operator)) _InquiryCard(operator: operator, phone: phone, netTab: netTab),
      if (services.isEmpty) const EmptyState(text: 'لا توجد خدمات منشورة لهذا المشغل في كتالوج الخادم.', icon: Icons.cloud_off_outlined),
      for (final s in services) _ServiceCard(service: s, color: color, phone: phone),
