class _InquiryCard extends StatefulWidget { const _InquiryCard({required this.operator, required this.phone, required this.netTab}); final String operator, netTab; final TextEditingController phone; @override State<_InquiryCard> createState() => _InquiryCardState(); }
class _InquiryCardState extends State<_InquiryCard> {
  bool busy = false; Map<String,dynamic>? result;
  @override Widget build(BuildContext context) => PageCard(padding: const EdgeInsets.all(11), child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
    Row(children: [const Icon(Icons.search_rounded, color: _blue), const SizedBox(width: 7), const Expanded(child: Text('استعلام مباشر من الخادم', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w900))), _pill(widget.operator == 'yemen_mobile' ? 'يمن موبايل' : widget.operator, _blue)]),
    const SizedBox(height: 8),
    SizedBox(width: double.infinity, child: FilledButton.icon(onPressed: busy ? null : _run, style: FilledButton.styleFrom(backgroundColor: serviceColor(widget.operator)), icon: busy ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white)) : const Icon(Icons.play_arrow_rounded), label: Text(busy ? 'جاري الاستعلام...' : 'استعلام الآن', style: const TextStyle(fontWeight: FontWeight.w900)))),
    if (result != null) ...[const SizedBox(height: 9), Container(padding: const EdgeInsets.all(10), decoration: BoxDecoration(color: const Color(0xFFECFEFF), borderRadius: BorderRadius.circular(13), border: Border.all(color: const Color(0xFFA5F3FC))), child: Column(children: [for (final e in result!.entries) if (e.value != null && '$e'.trim().isNotEmpty) Padding(padding: const EdgeInsets.symmetric(vertical: 2), child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text('${e.key}', style: const TextStyle(fontSize: 9, color: _muted)), Text('${e.value}', style: const TextStyle(fontSize: 10, fontWeight: FontWeight.w900))]))]))],
  ]));
  Future<void> _run() async { if (widget.phone.text.trim().isEmpty) return; setState(() => busy = true); try { final app = context.read<AppController>(); final services = app.servicesFor(widget.operator); if (services.isEmpty) throw Exception('لا توجد خدمة استعلام لهذا المشغل'); final s = services.first; result = await app.requestService(serviceId: int.parse('${s['id']}'), payload: {'mobile': widget.phone.text.trim(), 'type': widget.netTab}); if (mounted) setState(() {}); } catch (e) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString()))); } finally { if (mounted) setState(() => busy = false); } }
}

