class _ServiceDialogState extends State<_ServiceDialog> { final ctrls=<String,TextEditingController>{}; bool busy=false; @override void initState(){super.initState(); final f=widget.service['fields']; if(f is List) for(final x in f.whereType<Map>()){final k='${x['key']??''}'; ctrls[k]=TextEditingController(text:(k=='mobile'||k=='phone')?widget.phone.text:'${x['default']??''}');} if(widget.item!=null&&ctrls.containsKey('amount')&&ctrls['amount']!.text.isEmpty) ctrls['amount']!.text='${widget.item!['price']??''}';}
